// Legacy exception specification (generally discouraged)
void myFunction() throw(int, std::runtime_error);

// Modern approach using noexcept
void myNoexceptFunction() noexcept;

// Example showing inheritance and exception specifications
struct Base {
    virtual void myVirtualFunction() throw(int);
};

struct Derived : public Base {
    void myVirtualFunction() override throw(int, std::exception); //Okay: at least as restrictive as Base
    void myVirtualFunction2() override throw(); //Error: less restrictive than Base
};
